arguments.old_string:
def _calc(self, seq, *sequences: Sequence) -> float:
    if not seq:
        return 1
    maxes = []
    for c1 in sequences[0]:
        for s in seq:
            max_sim = float('inf')
            for c2 in s:
                max_sim = min(max_sim, self.algorithm.similarity(c1, c2))
            maxes.append(max_sim)
    return sum(maxes) / (len(seq) + 1) / len(maxes)

arguments.new_string:
def _calc(self, seq, *sequences: Sequence) -> float:
    if not seq:
        return 0
    maxes = []
    for c1 in seq:
        for s in sequences:
            max_sim = float('-inf')
            for c2 in s:
                max_sim = max(max_sim, self.algorithm.similarity(c1, c2))
            maxes.append(max_sim)
    return sum(maxes) / len(seq) / len(maxes)
